using System;
using System.Collections.Generic;
using UnityEngine;

namespace Game.Items
{
    /// <summary>Un stack de un mismo item dentro del inventario.</summary>
    public class ItemStack
    {
        /// <summary>Id del item.</summary>
        public string ItemId { get; }

        /// <summary>Cantidad en este stack.</summary>
        public int Count { get; set; }

        /// <summary>Crea un stack.</summary>
        public ItemStack(string itemId, int count)
        {
            ItemId = itemId;
            Count = count;
        }
    }

    /// <summary>Inventario con capacidad limitada de slots y stacks con tope.</summary>
    public class Inventory : MonoBehaviour
    {
        [SerializeField] private int _capacity = 10;
        [SerializeField] private int _maxStack = 99;

        private readonly List<ItemStack> _slots = new List<ItemStack>();

        /// <summary>Se dispara cada vez que el contenido cambia.</summary>
        public event Action OnInventoryChanged;

        /// <summary>Número máximo de slots.</summary>
        public int Capacity => _capacity;

        /// <summary>Slots ocupados (solo lectura).</summary>
        public IReadOnlyList<ItemStack> Slots => _slots;

        /// <summary>Agrega items. Devuelve la cantidad que NO cupo.</summary>
        public int AddItem(string itemId, int amount)
        {
            if (amount <= 0) return 0;

            int requested = amount;

            foreach (var stack in _slots)
            {
                if (stack.ItemId == itemId && stack.Count < _maxStack)
                {
                    int add = Mathf.Min(_maxStack - stack.Count, amount);
                    stack.Count += add;
                    amount -= add;
                }
            }

            while (amount > 0 && _slots.Count < _capacity)
            {
                int add = Mathf.Min(_maxStack, amount);
                _slots.Add(new ItemStack(itemId, add));
                amount -= add;
            }

            if (amount != requested) OnInventoryChanged?.Invoke();
            return amount;
        }

        /// <summary>Quita items. Devuelve false (sin cambiar nada) si no hay suficientes.</summary>
        public bool RemoveItem(string itemId, int amount)
        {
            if (amount <= 0) return true;
            if (GetCount(itemId) < amount) return false;

            for (int i = 0; i < _slots.Count; i++)
            {
                var stack = _slots[i];
                if (stack.ItemId != itemId) continue;

                int take = Mathf.Min(stack.Count, amount);
                stack.Count -= take;
                amount -= take;
                if (stack.Count == 0)
                {
                    _slots.RemoveAt(i);
                    i--;
                }
                if (amount == 0) break;
            }

            OnInventoryChanged?.Invoke();
            return true;
        }

        /// <summary>Total de unidades de un item.</summary>
        public int GetCount(string itemId)
        {
            int total = 0;
            foreach (var stack in _slots)
                if (stack.ItemId == itemId) total += stack.Count;
            return total;
        }
    }
}
